-- MARINA CAP MONASTIR - RESTORE REAL DATA FROM OLD SUPABASE
-- 100% Bulletproof & Resilient: Drops restrictive not-null constraints before inserting
-- ==============================================================================

-- 1. Relax constraints to match actual data
ALTER TABLE IF EXISTS public.room_types ADD COLUMN IF NOT EXISTS category text;
ALTER TABLE IF EXISTS public.room_types ADD COLUMN IF NOT EXISTS sort_order integer DEFAULT 0;
ALTER TABLE IF EXISTS public.room_types ALTER COLUMN type DROP NOT NULL;
ALTER TABLE IF EXISTS public.room_images ADD COLUMN IF NOT EXISTS image_url text;
ALTER TABLE IF EXISTS public.room_images ALTER COLUMN url DROP NOT NULL;
ALTER TABLE IF EXISTS public.guests ADD COLUMN IF NOT EXISTS cin_passport text;
ALTER TABLE IF EXISTS public.room_rate_calendar ADD COLUMN IF NOT EXISTS currency text DEFAULT 'TND';
ALTER TABLE IF EXISTS public.reservation_conversations ALTER COLUMN reservation_id DROP NOT NULL;
ALTER TABLE IF EXISTS public.reservation_conversations ALTER COLUMN owner_id DROP NOT NULL;

-- 2. Replace placeholder rooms with exact real historical rooms & IDs
TRUNCATE TABLE public.room_amenities, public.room_images, public.room_units, public.room_types CASCADE;

