-- 4. Regenerate physical units for restored room types
SELECT 'ae47c5a0-5915-4e45-a355-bcda4a85bb5a', 'ST-' || lpad(series::text, 3, '0'), 'available'
FROM generate_series(1, 10) AS series ON CONFLICT DO NOTHING;

SELECT 'be47c5a0-5915-4e45-a355-bcda4a85bb5b', 'ECO-' || lpad(series::text, 3, '0'), 'available'
FROM generate_series(1, 5) AS series ON CONFLICT DO NOTHING;

SELECT 'ce47c5a0-5915-4e45-a355-bcda4a85bb5c', 'STD-' || lpad(series::text, 3, '0'), 'available'
FROM generate_series(1, 5) AS series ON CONFLICT DO NOTHING;

SELECT 'de47c5a0-5915-4e45-a355-bcda4a85bb5d', 'S2-' || lpad(series::text, 3, '0'), 'available'
FROM generate_series(1, 5) AS series ON CONFLICT DO NOTHING;

UPDATE public.room_types SET type = COALESCE(category, 'Appartement') WHERE type IS NULL;
UPDATE public.room_images SET url = COALESCE(image_url, url) WHERE url IS NULL;
